  'about.license.core': { pt: 'Motor Principal do AgentOS', es: 'Motor Principal de AgentOS', fr: 'Moteur Principal AgentOS', de: 'AgentOS Core Engine', ja: 'AgentOS コアエンジン', ko: 'AgentOS 코어 엔진', zh: 'AgentOS 核心引擎' },
  'about.license.coreDesc': { pt: 'O runtime principal do AgentOS, orquestração de GMI e infraestrutura', es: 'El runtime principal de AgentOS, orquestación de GMI e infraestructura', fr: 'Le runtime principal AgentOS, l’orchestration GMI et l’infrastructure', de: 'Die Kern-Runtime von AgentOS, GMI-Orchestrierung und Infrastruktur', ja: 'AgentOS のコアランタイム、GMI オーケストレーション、インフラ', ko: 'AgentOS 코어 런타임, GMI 오케스트레이션, 인프라', zh: 'AgentOS 核心运行时、GMI 编排与基础设施' },
