  'benchmarks.highlightSAccuracy': { pt: 'AgentOS LongMemEval-S', es: 'AgentOS LongMemEval-S', fr: 'AgentOS LongMemEval-S', de: 'AgentOS LongMemEval-S', ja: 'AgentOS LongMemEval-S', ko: 'AgentOS LongMemEval-S', zh: 'AgentOS LongMemEval-S' },
  'benchmarks.highlightSValue': { pt: '85.6%', es: '85.6%', fr: '85,6%', de: '85,6%', ja: '85.6%', ko: '85.6%', zh: '85.6%' },
  'benchmarks.highlightSCi': { pt: 'Roteador de leitor por categoria (gpt-4o + gpt-5-mini) · 84.2% só com gpt-4o, empatado com Mastra OM gpt-4o (84.23%) · $0.0090 por acerto · latência mediana de 3.6 segundos', es: 'Router de lector por categoría (gpt-4o + gpt-5-mini) · 84.2% solo con gpt-4o, a la par de Mastra OM gpt-4o (84.23%) · $0.0090 por acierto · latencia mediana de 3.6 segundos', fr: 'Routeur de lecteur par catégorie (gpt-4o + gpt-5-mini) · 84.2% avec gpt-4o seul, à égalité avec Mastra OM gpt-4o (84.23%) · $0.0090 par bonne réponse · latence médiane de 3.6 secondes', de: 'Reader-Router pro Kategorie (gpt-4o + gpt-5-mini) · 84.2% nur mit gpt-4o, gleichauf mit Mastra OM gpt-4o (84.23%) · $0.0090 pro richtiger Antwort · 3.6 Sekunden mediane Latenz', ja: 'カテゴリ別リーダールーター（gpt-4o + gpt-5-mini）· gpt-4o のみで 84.2%、Mastra OM gpt-4o（84.23%）と同等 · 正解あたり $0.0090 · レイテンシ中央値 3.6 秒', ko: '범주별 리더 라우터(gpt-4o + gpt-5-mini) · gpt-4o만으로 84.2%, Mastra OM gpt-4o(84.23%)와 동률 · 정답당 $0.0090 · 지연 시간 중앙값 3.6초', zh: '按类别的读取模型路由（gpt-4o + gpt-5-mini）· 仅用 gpt-4o 为 84.2%，与 Mastra OM gpt-4o（84.23%）持平 · 每个正确答案 $0.0090 · 中位延迟 3.6 秒' },
  'benchmarks.highlightMAccuracy': { pt: 'AgentOS LongMemEval-M', es: 'AgentOS LongMemEval-M', fr: 'AgentOS LongMemEval-M', de: 'AgentOS LongMemEval-M', ja: 'AgentOS LongMemEval-M', ko: 'AgentOS LongMemEval-M', zh: 'AgentOS LongMemEval-M' },
  'benchmarks.highlightMValue': { pt: '70.2%', es: '70.2%', fr: '70,2%', de: '70,2%', ja: '70.2%', ko: '70.2%', zh: '70.2%' },
  'benchmarks.highlightMCi': { pt: 'Roteador de leitor por categoria, recuperação top-5 · $0.0078 por acerto · a melhor configuração com GPT-4o do artigo do LongMemEval marca 72.0% em top-10', es: 'Router de lector por categoría, recuperación top-5 · $0.0078 por acierto · la mejor configuración con GPT-4o del artículo de LongMemEval obtiene 72.0% en top-10', fr: 'Routeur de lecteur par catégorie, récupération top-5 · $0.0078 par bonne réponse · la meilleure configuration GPT-4o de l’article LongMemEval obtient 72.0% en top-10', de: 'Reader-Router pro Kategorie, Top-5-Retrieval · $0.0078 pro richtiger Antwort · das beste GPT-4o-Setup des LongMemEval-Papers erreicht 72.0% bei Top-10', ja: 'カテゴリ別リーダールーター、top-5 検索 · 正解あたり $0.0078 · LongMemEval 論文の GPT-4o 最良構成は top-10 で 72.0%', ko: '범주별 리더 라우터, top-5 검색 · 정답당 $0.0078 · LongMemEval 논문의 최고 GPT-4o 설정은 top-10에서 72.0%', zh: '按类别的读取模型路由，top-5 检索 · 每个正确答案 $0.0078 · LongMemEval 论文中最佳 GPT-4o 配置在 top-10 下为 72.0%' },
  'benchmarks.matrixIntro': { pt: 'As linhas do AgentOS e a reexecução do EmergenceMem Simple Fast vêm de execuções do agentos-bench nos conjuntos de 500 perguntas do LongMemEval, avaliadas pelo gpt-4o-2024-08-06 com a rubrica do LongMemEval. As linhas dos fornecedores são os números que cada um publica.', es: 'Las filas de AgentOS y la repetición de EmergenceMem Simple Fast provienen de ejecuciones de agentos-bench sobre los conjuntos de 500 preguntas de LongMemEval, evaluadas por gpt-4o-2024-08-06 con la rúbrica de LongMemEval. Las filas de proveedores son las cifras que cada uno publica.', fr: 'Les lignes AgentOS et la réexécution d’EmergenceMem Simple Fast viennent d’exécutions d’agentos-bench sur les jeux de 500 questions de LongMemEval, jugées par gpt-4o-2024-08-06 avec la grille de LongMemEval. Les lignes des fournisseurs reprennent les chiffres que chacun publie.', de: 'Die AgentOS-Zeilen und der Nachlauf von EmergenceMem Simple Fast stammen aus agentos-bench-Läufen auf den 500-Fragen-Sätzen von LongMemEval, bewertet von gpt-4o-2024-08-06 mit dem LongMemEval-Rubric. Die Anbieterzeilen sind die Zahlen, die jeder Anbieter veröffentlicht.', ja: 'AgentOS の行と EmergenceMem Simple Fast の再実行は、500 問の LongMemEval セットに対する agentos-bench の実行結果で、LongMemEval の評価基準に沿って gpt-4o-2024-08-06 が採点しています。ベンダーの行は各社が公表した数値です。', ko: 'AgentOS 행과 EmergenceMem Simple Fast 재실행은 500문항 LongMemEval 세트에 대한 agentos-bench 실행 결과이며, LongMemEval 채점 기준으로 gpt-4o-2024-08-06이 채점했습니다. 벤더 행은 각 벤더가 공개한 수치입니다.', zh: 'AgentOS 各行以及 EmergenceMem Simple Fast 的复现结果来自 agentos-bench 在 500 题 LongMemEval 数据集上的运行，由 gpt-4o-2024-08-06 按 LongMemEval 评分标准判分。厂商行是各厂商公布的数字。' },
